1	import { describe, expect, mock, test } from "bun:test";
2	import * as products from "../src/products";
3	import { getWishlist, removeFromWishlist, saveToWishlist } from "../src/wishlist";
4	
5	describe("wishlist", () => {
6	  test("saves a catalogue product [wishlist/keep-a-wishlist#save-a-product]", () => {
7	    const saved = saveToWishlist("c-save-a-product", "rain-jacket");
8	    expect(saved.map((item) => item.productId)).toEqual(["rain-jacket"]);
9	    expect(getWishlist("c-save-a-product").map((item) => item.productId)).toEqual(["rain-jacket"]);
10	  });
11	
12	  test("refuses a product the catalogue does not hold [wishlist/keep-a-wishlist#catalogue-products-only]", () => {
13	    expect(() => saveToWishlist("c-catalogue-products-only", "tent")).toThrow("Unknown product: tent");
14	    expect(getWishlist("c-catalogue-products-only")).toEqual([]);
15	  });
16	
17	  test("holds a product without a quantity [wishlist/keep-a-wishlist#no-quantity]", () => {
18	    saveToWishlist("c-no-quantity", "wool-socks");
19	    expect(getWishlist("c-no-quantity")).toEqual([
20	      { productId: "wool-socks", name: "Wool socks", priceCents: 1200 },
21	    ]);
22	  });
23	
24	  test("keeps one entry where the first save put it [wishlist/keep-a-wishlist#saved-once]", () => {
25	    saveToWishlist("c-saved-once", "wool-socks");
26	    saveToWishlist("c-saved-once", "headlamp");
27	    saveToWishlist("c-saved-once", "wool-socks");
28	    expect(getWishlist("c-saved-once").map((item) => item.productId)).toEqual(["headlamp", "wool-socks"]);
29	  });
30	
31	  test("removes a saved product [wishlist/keep-a-wishlist#remove-a-product]", () => {
32	    saveToWishlist("c-remove-a-product", "rain-jacket");
33	    saveToWishlist("c-remove-a-product", "wool-socks");
34	    const left = removeFromWishlist("c-remove-a-product", "wool-socks");
35	    expect(left.map((item) => item.productId)).toEqual(["rain-jacket"]);
36	    expect(getWishlist("c-remove-a-product").map((item) => item.productId)).toEqual(["rain-jacket"]);
37	  });
38	
39	  test("refuses to remove a product that is not saved [wishlist/keep-a-wishlist#remove-saved-only]", () => {
40	    saveToWishlist("c-remove-saved-only", "rain-jacket");
41	    expect(() => removeFromWishlist("c-remove-saved-only", "headlamp")).toThrow(
42	      "Product headlamp is not on the wishlist",
43	    );
44	    expect(getWishlist("c-remove-saved-only").map((item) => item.productId)).toEqual(["rain-jacket"]);
45	  });
46	
47	  test("shows one customer only their own saved items [wishlist/see-the-wishlist#one-list-per-customer]", () => {
48	    saveToWishlist("c-one-list-per-customer-1", "headlamp");
49	    expect(getWishlist("c-one-list-per-customer-1").map((item) => item.productId)).toEqual(["headlamp"]);
50	    expect(getWishlist("c-one-list-per-customer-2")).toEqual([]);
51	  });
52	
53	  test("reads an empty wishlist for a customer who has saved nothing [wishlist/see-the-wishlist#empty-wishlist]", () => {
54	    expect(getWishlist("c-empty-wishlist")).toEqual([]);
55	  });
56	
57	  test("shows the price the catalogue holds now [wishlist/see-the-wishlist#price-now]", () => {
58	    saveToWishlist("c-price-now", "rain-jacket");
59	    expect(getWishlist("c-price-now")).toEqual([
60	      { productId: "rain-jacket", name: "Rain jacket", priceCents: 1990 },
61	    ]);
62	
63	    const catalogueGetProduct = products.getProduct;
64	    mock.module("../src/products", () => ({
65	      ...products,
66	      getProduct: (id: string) => ({ ...catalogueGetProduct(id), priceCents: 2490 }),
67	    }));
68	    try {
69	      expect(getWishlist("c-price-now")).toEqual([
70	        { productId: "rain-jacket", name: "Rain jacket", priceCents: 2490 },
71	      ]);
72	    } finally {
73	      mock.module("../src/products", () => ({ ...products, getProduct: catalogueGetProduct }));
74	    }
75	    expect(getWishlist("c-price-now")).toEqual([
76	      { productId: "rain-jacket", name: "Rain jacket", priceCents: 1990 },
77	    ]);
78	  });
79	
80	  test("shows the most recently saved item first [wishlist/see-the-wishlist#newest-first]", () => {
81	    saveToWishlist("c-newest-first", "wool-socks");
82	    saveToWishlist("c-newest-first", "headlamp");
83	    expect(getWishlist("c-newest-first").map((item) => item.name)).toEqual(["Headlamp", "Wool socks"]);
84	  });
85	});
