1	export type Product = { id: string; name: string; priceCents: number };
2	
3	const catalogue: Product[] = [
4	  { id: "rain-jacket", name: "Rain jacket", priceCents: 1990 },
5	  { id: "wool-socks", name: "Wool socks", priceCents: 1200 },
6	  { id: "water-bottle", name: "Water bottle", priceCents: 2000 },
7	  { id: "trail-map", name: "Trail map", priceCents: 850 },
8	  { id: "headlamp", name: "Headlamp", priceCents: 3499 },
9	];
10	
11	export function listProducts(): Product[] {
12	  return catalogue.map((p) => ({ ...p }));
13	}
14	
15	export function getProduct(id: string): Product {
16	  const product = catalogue.find((p) => p.id === id);
17	  if (!product) throw new Error(`Unknown product: ${id}`);
18	  return { ...product };
19	}
